content:
300      GetHelpData().mNextOptionOffset += optionLength;
   301
   302  exit:
   303      if (error == OT_ERROR_PARSE)
   304      {
   305          GetHelpData().mNextOptionOffset = 0;
   306      }
   307
   308      return rval;
   309  }
