   325  otError Message::SetPayloadMarker(void)
   326  {
   327      otError error  = OT_ERROR_NONE;
   328      uint8_t marker = 0xff;
   329
   330      VerifyOrExit(GetLength() < kMaxHeaderLength, error = OT_ERROR_NO_BUFS);
   331      SuccessOrExit(error = Append(&marker, sizeof(marker)));
   332      GetHelpData().mHeaderLength = GetLength();
   333
   334      // Set offset to the start of payload.
   335      SetOffset(GetHelpData().mHeaderLength);
   336
   337  exit:
   338      return error;
   339  }
