   341  otError Message::ParseHeader(void)
   342  {
   343      otError error = OT_ERROR_NONE;
   344
   345      assert(mBuffer.mHead.mInfo.mReserved >=
   346             sizeof(GetHelpData()) +
   347                 static_cast<size_t>((reinterpret_cast<uint8_t *>(&GetHelpData()) - mBuffer.mHead.mData)));
   348
   349      memset(&GetHelpData(), 0, sizeof(GetHelpData()));
   350
   351      GetHelpData().mHeaderOffset = GetOffset();
   352      Read(GetHelpData().mHeaderOffset, sizeof(GetHelpData().mHeader), &GetHelpData().mHeader);
   353
   354      for (const otCoapOption *option = GetFirstOption(); option != NULL; option = GetNextOption())
   355      {
   356      }
   357
   358      VerifyOrExit(GetHelpData().mNextOptionOffset > 0, error = OT_ERROR_PARSE);
   359      GetHelpData().mHeaderLength = GetHelpData().mNextOptionOffset - GetHelpData().mHeaderOffset;
   360      MoveOffset(GetHelpData().mHeaderLength);
   361
   362  exit:
   363      return error;
   364  }
