   366  otError Message::SetToken(const uint8_t *aToken, uint8_t aTokenLength)
   367  {
   368      GetHelpData().mHeader.mVersionTypeToken = (GetHelpData().mHeader.mVersionTypeToken & ~kTokenLengthMask) |
   369                                                ((aTokenLength << kTokenLengthOffset) & kTokenLengthMask);
   370      memcpy(GetHelpData().mHeader.mToken, aToken, aTokenLength);
   371      GetHelpData().mHeaderLength += aTokenLength;
   372
   373      return SetLength(GetHelpData().mHeaderLength);
   374  }
   375
   376  otError Message::SetToken(uint8_t aTokenLength)
   377  {
   378      uint8_t token[kMaxTokenLength] = {0};
   379
   380      assert(aTokenLength <= sizeof(token));
   381
   382      Random::NonCrypto::FillBuffer(token, aTokenLength);
   383
   384      return SetToken(token, aTokenLength);
   385  }
